-- EstateVista initial schema. Generated from prisma/schema.prisma.
CREATE TYPE "Role" AS ENUM ('SUPER_ADMIN','ADMIN','EDITOR'); CREATE TYPE "Purpose" AS ENUM ('SALE','RENT'); CREATE TYPE "PublicationStatus" AS ENUM ('DRAFT','PUBLISHED'); CREATE TYPE "AvailabilityStatus" AS ENUM ('AVAILABLE','PENDING','SOLD','RENTED'); CREATE TYPE "LeadStatus" AS ENUM ('NEW','CONTACTED','QUALIFIED','VIEWING_SCHEDULED','CLOSED_WON','CLOSED_LOST','SPAM'); CREATE TYPE "SubmissionStatus" AS ENUM ('PENDING','APPROVED','REJECTED','CONVERTED');
CREATE TABLE "AdminUser" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'ADMIN',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"slug" TEXT NOT NULL UNIQUE,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Location" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"city" TEXT NOT NULL,"area" TEXT,"slug" TEXT NOT NULL UNIQUE,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Agent" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"role" TEXT NOT NULL,"bio" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"phone" TEXT NOT NULL,"whatsapp" TEXT NOT NULL,"photoUrl" TEXT,"facebook" TEXT,"instagram" TEXT,"linkedin" TEXT,"displayOrder" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Amenity" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"slug" TEXT NOT NULL UNIQUE);
CREATE TABLE "Property" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"referenceId" TEXT NOT NULL UNIQUE,"description" TEXT NOT NULL,"purpose" "Purpose" NOT NULL,"price" DECIMAL(18,2) NOT NULL,"oldPrice" DECIMAL(18,2),"currency" TEXT NOT NULL DEFAULT 'PKR',"city" TEXT NOT NULL,"locality" TEXT,"address" TEXT NOT NULL,"latitude" DECIMAL(10,7),"longitude" DECIMAL(10,7),"size" DECIMAL(12,2) NOT NULL,"sizeUnit" TEXT NOT NULL DEFAULT 'sq ft',"bedrooms" INTEGER NOT NULL DEFAULT 0,"bathrooms" INTEGER NOT NULL DEFAULT 0,"garages" INTEGER NOT NULL DEFAULT 0,"yearBuilt" INTEGER,"videoTourUrl" TEXT,"featured" BOOLEAN NOT NULL DEFAULT false,"publicationStatus" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"availabilityStatus" "AvailabilityStatus" NOT NULL DEFAULT 'AVAILABLE',"seoTitle" TEXT,"seoDescription" TEXT,"categoryId" TEXT NOT NULL REFERENCES "Category"("id") ON DELETE RESTRICT,"locationId" TEXT NOT NULL REFERENCES "Location"("id") ON DELETE RESTRICT,"agentId" TEXT REFERENCES "Agent"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PropertyImage" ("id" TEXT PRIMARY KEY,"url" TEXT NOT NULL,"publicId" TEXT,"altText" TEXT,"isPrimary" BOOLEAN NOT NULL DEFAULT false,"sortOrder" INTEGER NOT NULL DEFAULT 0,"propertyId" TEXT NOT NULL REFERENCES "Property"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PropertyAmenity" ("propertyId" TEXT NOT NULL REFERENCES "Property"("id") ON DELETE CASCADE,"amenityId" TEXT NOT NULL REFERENCES "Amenity"("id") ON DELETE RESTRICT,PRIMARY KEY("propertyId","amenityId"));
CREATE TABLE "Inquiry" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"message" TEXT,"status" "LeadStatus" NOT NULL DEFAULT 'NEW',"adminNotes" TEXT,"isRead" BOOLEAN NOT NULL DEFAULT false,"propertyId" TEXT REFERENCES "Property"("id") ON DELETE SET NULL,"agentId" TEXT REFERENCES "Agent"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ViewingRequest" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"message" TEXT,"preferredDate" TIMESTAMP(3) NOT NULL,"preferredTime" TEXT NOT NULL,"status" "LeadStatus" NOT NULL DEFAULT 'NEW',"adminNotes" TEXT,"isRead" BOOLEAN NOT NULL DEFAULT false,"propertyId" TEXT NOT NULL REFERENCES "Property"("id") ON DELETE CASCADE,"agentId" TEXT REFERENCES "Agent"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ContactMessage" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"subject" TEXT NOT NULL,"message" TEXT NOT NULL,"status" "LeadStatus" NOT NULL DEFAULT 'NEW',"isRead" BOOLEAN NOT NULL DEFAULT false,"adminNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PropertySubmission" ("id" TEXT PRIMARY KEY,"ownerName" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"whatsapp" TEXT NOT NULL,"purpose" "Purpose" NOT NULL,"propertyType" TEXT NOT NULL,"title" TEXT NOT NULL,"city" TEXT NOT NULL,"address" TEXT NOT NULL,"expectedPrice" DECIMAL(18,2) NOT NULL,"area" DECIMAL(12,2) NOT NULL,"bedrooms" INTEGER NOT NULL DEFAULT 0,"bathrooms" INTEGER NOT NULL DEFAULT 0,"description" TEXT NOT NULL,"agreement" BOOLEAN NOT NULL,"status" "SubmissionStatus" NOT NULL DEFAULT 'PENDING',"rejectionReason" TEXT,"convertedPropertyId" TEXT UNIQUE REFERENCES "Property"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SubmissionImage" ("id" TEXT PRIMARY KEY,"url" TEXT NOT NULL,"publicId" TEXT,"submissionId" TEXT NOT NULL REFERENCES "PropertySubmission"("id") ON DELETE CASCADE);
CREATE TABLE "Testimonial" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"role" TEXT,"quote" TEXT NOT NULL,"rating" INTEGER NOT NULL DEFAULT 5,"photoUrl" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"displayOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "NewsletterSubscriber" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SiteSetting" ("id" TEXT PRIMARY KEY DEFAULT 'main',"agencyName" TEXT NOT NULL DEFAULT 'EstateVista Properties',"logoUrl" TEXT,"faviconUrl" TEXT,"primaryPhone" TEXT,"whatsapp" TEXT,"email" TEXT,"officeAddress" TEXT,"businessHours" TEXT,"currency" TEXT NOT NULL DEFAULT 'PKR',"facebook" TEXT,"instagram" TEXT,"linkedin" TEXT,"defaultSeoTitle" TEXT,"defaultSeoDescription" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "HomepageSection" ("id" TEXT PRIMARY KEY DEFAULT 'main',"heroHeading" TEXT NOT NULL,"heroDescription" TEXT NOT NULL,"heroBackgroundImage" TEXT,"aboutTitle" TEXT,"aboutContent" TEXT,"footerText" TEXT,"statistics" JSONB,"popularLocations" JSONB,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Property_purpose_publicationStatus_availabilityStatus_idx" ON "Property"("purpose","publicationStatus","availabilityStatus"); CREATE INDEX "Property_city_price_idx" ON "Property"("city","price"); CREATE INDEX "Inquiry_status_createdAt_idx" ON "Inquiry"("status","createdAt");
